import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.DaGSOal_.js";const p=JSON.parse('{"title":"Features","description":"","frontmatter":{"sidebar_position":3},"headers":[],"relativePath":"duplicate-asset-detector/features.md","filePath":"duplicate-asset-detector/features.md","lastUpdated":1772615207000}'),s={name:"duplicate-asset-detector/features.md"};function n(r,e,o,c,d,u){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><h2 id="smart-detection" tabindex="-1">Smart Detection <a class="header-anchor" href="#smart-detection" aria-label="Permalink to &quot;Smart Detection&quot;">​</a></h2><h3 id="content-based-hashing" tabindex="-1">Content-Based Hashing <a class="header-anchor" href="#content-based-hashing" aria-label="Permalink to &quot;Content-Based Hashing&quot;">​</a></h3><p>Duplicate Asset Detector uses advanced content-based hashing to find <strong>true duplicates</strong>, not just similarly named files. This means:</p><ul><li>Textures with identical pixels are detected, even with different names</li><li>Materials with the same parameters are identified</li><li>Static Meshes with identical geometry are found</li></ul><h3 id="intelligent-filtering" tabindex="-1">Intelligent Filtering <a class="header-anchor" href="#intelligent-filtering" aria-label="Permalink to &quot;Intelligent Filtering&quot;">​</a></h3><p>The plugin automatically excludes:</p><ul><li>Level actors and instances</li><li>Engine content (unless you want to include it)</li><li>System files and special assets</li><li>Plugin content (optional)</li></ul><h3 id="special-asset-handling" tabindex="-1">Special Asset Handling <a class="header-anchor" href="#special-asset-handling" aria-label="Permalink to &quot;Special Asset Handling&quot;">​</a></h3><p>Optimized detection for:</p><ul><li>Materials and Material Instances</li><li>Textures (Texture2D, TextureCube, RenderTarget)</li><li>Static Meshes and Skeletal Meshes</li><li>Sounds (SoundWave, SoundCue)</li><li>Blueprints and C++ Classes</li><li>Data Tables and Curves</li><li>And many more</li></ul><h2 id="safe-cleanup" tabindex="-1">Safe Cleanup <a class="header-anchor" href="#safe-cleanup" aria-label="Permalink to &quot;Safe Cleanup&quot;">​</a></h2><h3 id="redirect-delete" tabindex="-1">Redirect &amp; Delete <a class="header-anchor" href="#redirect-delete" aria-label="Permalink to &quot;Redirect &amp; Delete&quot;">​</a></h3><p>The safest way to remove duplicates:</p><ol><li>Automatically updates all references to point to the kept asset</li><li>Deletes the duplicate asset</li><li>Preserves all functionality in your project</li><li>No broken references or missing assets</li></ol><h3 id="delete-only" tabindex="-1">Delete Only <a class="header-anchor" href="#delete-only" aria-label="Permalink to &quot;Delete Only&quot;">​</a></h3><p>For advanced users who are certain:</p><ul><li>Quickly removes duplicates without redirection</li><li>Useful when you&#39;ve already manually updated references</li><li>Use with caution</li></ul><h3 id="preview-before-delete" tabindex="-1">Preview Before Delete <a class="header-anchor" href="#preview-before-delete" aria-label="Permalink to &quot;Preview Before Delete&quot;">​</a></h3><p>Always see what will be affected:</p><ul><li>List of all assets to be deleted</li><li>All referencers that will be updated</li><li>Estimated disk space savings</li><li>Review before confirming</li></ul><h2 id="flexible-scanning" tabindex="-1">Flexible Scanning <a class="header-anchor" href="#flexible-scanning" aria-label="Permalink to &quot;Flexible Scanning&quot;">​</a></h2><h3 id="scan-options" tabindex="-1">Scan Options <a class="header-anchor" href="#scan-options" aria-label="Permalink to &quot;Scan Options&quot;">​</a></h3><ul><li><strong>Entire Project:</strong> Analyze all assets in your Content folder</li><li><strong>Specific Folders:</strong> Right-click any folder → Find Duplicates</li><li><strong>Custom Paths:</strong> Enter manual paths for specialized scans</li></ul><h3 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h3><ul><li>Filter by asset type (Textures, Materials, Meshes, etc.)</li><li>Set minimum file size threshold</li><li>Exclude specific folder patterns</li><li>Include/exclude Engine content</li><li>Include/exclude Plugin content</li></ul><h2 id="detailed-analysis" tabindex="-1">Detailed Analysis <a class="header-anchor" href="#detailed-analysis" aria-label="Permalink to &quot;Detailed Analysis&quot;">​</a></h2><h3 id="asset-information" tabindex="-1">Asset Information <a class="header-anchor" href="#asset-information" aria-label="Permalink to &quot;Asset Information&quot;">​</a></h3><p>For each duplicate pair, see:</p><ul><li>File size (disk space)</li><li>Number of dependencies</li><li>Number of referencers</li><li>Visual thumbnail preview</li><li>Asset type and package path</li></ul><h3 id="wasted-space-calculation" tabindex="-1">Wasted Space Calculation <a class="header-anchor" href="#wasted-space-calculation" aria-label="Permalink to &quot;Wasted Space Calculation&quot;">​</a></h3><p>The plugin calculates:</p><ul><li>Total duplicate size across your project</li><li>Potential savings per duplicate pair</li><li>Accumulated savings if all duplicates are removed</li></ul><h3 id="export-reports" tabindex="-1">Export Reports <a class="header-anchor" href="#export-reports" aria-label="Permalink to &quot;Export Reports&quot;">​</a></h3><p>Export your findings to:</p><ul><li><strong>CSV</strong> - For spreadsheet analysis</li><li><strong>Excel</strong> - With formatting and charts</li><li><strong>JSON</strong> - For custom processing</li><li><strong>Full Report</strong> - Comprehensive project analysis</li></ul><h2 id="important-notes" tabindex="-1">Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to &quot;Important Notes&quot;">​</a></h2><h3 id="assets-in-use-warning" tabindex="-1">Assets in Use Warning <a class="header-anchor" href="#assets-in-use-warning" aria-label="Permalink to &quot;Assets in Use Warning&quot;">​</a></h3><p>When deleting assets currently used in an open level, Unreal Engine may display a warning (&quot;asset is already in use&quot;). This is normal engine behavior - the redirect operation completes successfully.</p><p><strong>For best results:</strong></p><ul><li>Close levels that reference duplicate assets before deletion</li><li>Alternatively, reload the project after performing redirects</li></ul><h3 id="detection-accuracy" tabindex="-1">Detection Accuracy <a class="header-anchor" href="#detection-accuracy" aria-label="Permalink to &quot;Detection Accuracy&quot;">​</a></h3><p>While Duplicate Asset Detector uses advanced content-based hashing, in rare cases false positives may occur with:</p><ul><li>Complex procedurally generated assets</li><li>Assets with similar but not identical content</li><li>Special engine-internal assets</li></ul><p>If you encounter an incorrectly flagged asset, please report it via Discord or email.</p>',45)])])}const f=a(s,[["render",n]]);export{p as __pageData,f as default};
